      if (provider === 'guangya') return '\u8BF7\u4F7F\u7528\u5149\u9E2D App \u626B\u7801\u786E\u8BA4\uFF0C\u626B\u5B8C\u540E\u70B9\u51FB\u201C\u626B\u7801\u540E\u70B9\u6211\u201D';
